packet=json.loads((TASK/'concept-baseline.json').read_text(encoding='utf-8'))
records=[]
for chapter,mapping in [('ch:PLACE-FIELDS',P5),('ch:SYNTHESIS',P6)]:
    ps=[p for p in packet['passages'] if p['chapter_id']==chapter]
    prose=[p for p in ps if p['kind']=='prose' and not re.fullmatch(r'<div[^>]*>|</div>',p['text'])]
    assert set(mapping)=={p['line'] for p in prose},(chapter,set(mapping) ^ {p['line'] for p in prose})
    for i,p in enumerate(prose):
        action='retain'
        if chapter=='ch:PLACE-FIELDS' and p['line'] in [272,377,385,391,393,403]: action='move into optional fold after visible result'
        if chapter=='ch:PLACE-FIELDS' and p['line'] in [311,339,345]: action='retain locus inside optional fold'
        if chapter=='ch:PLACE-FIELDS' and p['line'] in [280,403]: action+='; repair result connector'
        before=mapping[prose[i-1]['line']] if i else 'Chapter opening follows the already read audience and prerequisite path.'
        after=mapping[prose[i+1]['line']] if i+1<len(prose) else 'End of chapter prepares the next reading step.'
        records.append(dict(passage_id=p['id'],line=p['line'],end_line=p['end_line'],path=p['path'],sha256=p['sha256'],opening=p['text'][:100],purpose=mapping[p['line']],previous_contribution=before,next_contribution=after,decision=action,order_reason='The stated contribution needs the preceding established objects and supplies the following purpose; '+mapping[p['line']]))
    for p in ps:
        if p['kind']=='block' or re.fullmatch(r'<div[^>]*>|</div>',p['text']):
            records.append(dict(passage_id=p['id'],line=p['line'],path=p['path'],sha256=p['sha256'],kind=p['kind'],decision='retain at original locus and keep visible',purpose='Keep the figure or table with its unchanged lead and interpretation.' if p['kind']=='block' else 'Preserve the existing scroll or responsive wrapper around its figure/table.'))

(HERE/'paragraph-purpose-order.json').write_text(json.dumps(records,ensure_ascii=False,indent=2),encoding='utf-8')
print('Paragraph records:',len(records))
